@Injectable()
export class ParseObjectIdPipe implements PipeTransform<string, Types.ObjectId> {
  transform(value: string, metadata: ArgumentMetadata): Types.ObjectId {
    if (!Types.ObjectId.isValid(value)) {
      // metadata.data === the param name, e.g. 'id'
      throw new BadRequestException(`${metadata.data} is not a valid ObjectId`);
    }
    return new Types.ObjectId(value); // transformed value reaches the handler
  }
}

