export const IS_PUBLIC_KEY = 'isPublic';
export const Public = () => SetMetadata(IS_PUBLIC_KEY, true);

@Injectable()
export class JwtAuthGuard extends AuthGuard('jwt') {
  constructor(private reflector: Reflector) { super(); }

  canActivate(ctx: ExecutionContext) {
    const isPublic = this.reflector.getAllAndOverride<boolean>(IS_PUBLIC_KEY, [
      ctx.getHandler(), ctx.getClass(),
    ]);
    if (isPublic) return true;      // skip auth for @Public() routes
    return super.canActivate(ctx);  // delegates to JwtStrategy.validate()
  }
}

// AppModule: { provide: APP_GUARD, useClass: JwtAuthGuard } // DI works here

export enum Role { User = 'user', Admin = 'admin' }
export const ROLES_KEY = 'roles';
export const Roles = (...roles: Role[]) => SetMetadata(ROLES_KEY, roles);

@Injectable()
export class RolesGuard implements CanActivate {
  constructor(private reflector: Reflector) {}
  canActivate(ctx: ExecutionContext): boolean {
    const required = this.reflector.getAllAndOverride<Role[]>(ROLES_KEY, [
      ctx.getHandler(), ctx.getClass(), // method overrides class
    ]);
    if (!required) return true; // opt-in: undecorated routes pass
    const { user } = ctx.switchToHttp().getRequest();
    return required.some((role) => user?.roles?.includes(role));
  }
}

// Usage: @Roles(Role.Admin) @UseGuards(JwtAuthGuard, RolesGuard) — authn first

@Injectable()
export class LoggingInterceptor implements NestInterceptor {
  intercept(ctx: ExecutionContext, next: CallHandler): Observable<any> {
    const started = Date.now();                       // pre-handler
    const req = ctx.switchToHttp().getRequest();
    return next.handle().pipe(                        // post-handler stream
      timeout(5000),                                  // unblocks client only!
      map((data) => ({ data, tookMs: Date.now() - started })), // envelope
      tap({
        error: (err) =>
          console.error(`${req.method} ${req.url} failed`, err.message),
      }),
      catchError((err) =>
        err instanceof TimeoutError
          ? throwError(() => new RequestTimeoutException())
          : throwError(() => err),
      ),
    );
  }
}

@Catch() // no args = catch-all
export class AllExceptionsFilter implements ExceptionFilter {
  constructor(private readonly logger: LoggerService) {} // DI via APP_FILTER

  catch(exception: unknown, host: ArgumentsHost) {
    const ctx = host.switchToHttp();
    const res = ctx.getResponse<Response>();

    const status = exception instanceof HttpException
      ? exception.getStatus()
      : HttpStatus.INTERNAL_SERVER_ERROR;

    if (status >= 500) this.logger.error(exception); // log real cause server-side

    res.status(status).json({
      statusCode: status,
      message: status >= 500 ? 'Internal server error' // never leak internals
        : (exception as HttpException).message,
      timestamp: new Date().toISOString(),
    });
  }
}
