@Injectable()
export class TransferService {
  constructor(private readonly dataSource: DataSource) {}

  async transfer(fromId: string, toId: string, amount: number) {
    return this.dataSource.transaction(async (em) => {
      // MUST use `em` — an injected Repository would run OUTSIDE the tx
      const from = await em.findOneByOrFail(Account, { id: fromId });
      const to = await em.findOneByOrFail(Account, { id: toId });
      from.balance -= amount;
      to.balance += amount;
      await em.save([from, to]); // throw anywhere -> automatic rollback
    });
  }
}

@WebSocketGateway({ namespace: 'chat', cors: true })
export class ChatGateway implements OnGatewayConnection, OnGatewayDisconnect {
  @WebSocketServer() server: Server;

  handleConnection(client: Socket) {
    // Auth at connection time — no per-message headers exist
    try {
      const payload = this.jwt.verify(client.handshake.auth.token);
      client.data.userId = payload.sub;
    } catch {
      client.disconnect(); // reject bad connections early
    }
  }

  handleDisconnect(client: Socket) { /* presence cleanup */ }

  @SubscribeMessage('message:send')
  onMessage(@MessageBody() dto: SendMessageDto, @ConnectedSocket() client: Socket) {
    this.server.to(dto.roomId).emit('message:new', dto); // broadcast to room
    return { status: 'ok' }; // acknowledgement back to sender
  }
}

// producer — inside a request handler, respond fast, work later
@Injectable()
export class MailService {
  constructor(@InjectQueue('mail') private queue: Queue) {}
  async queueWelcome(userId: string) {
    await this.queue.add('welcome', { userId }, {
      attempts: 3,
      backoff: { type: 'exponential', delay: 1000 },
      removeOnComplete: true,
    });
  }
}

// consumer — BullMQ style
@Processor('mail')
export class MailProcessor extends WorkerHost {
  async process(job: Job<{ userId: string }>) {
    if (job.name === 'welcome') await this.mailer.sendWelcome(job.data.userId);
    // throwing here = failed attempt -> retried per `attempts`
  }
}

